import { Component, OnInit } from '@angular/core';
import { MisComprasService } from 'src/app/services/mis-compras.service';
import { UsuarioService } from 'src/app/services/usuario.service';

@Component({
  selector: 'app-total-compras-todos-usuarios',
  templateUrl: './total-compras-todos-usuarios.component.html',
  styleUrls: ['./total-compras-todos-usuarios.component.css']
})
export class TotalComprasTodosUsuariosComponent implements OnInit{

  public totalCompras: number | null = null;

  constructor(public misComprasService: MisComprasService, public usuarioService: UsuarioService){}

  ngOnInit(): void {
    this.contarComprasUsuarios();
  }


  contarComprasUsuarios(){

    this.misComprasService.contarComprasUsuarios().subscribe(
      (res: {totalCompras : number}) => {
        this.totalCompras = res.totalCompras;
      });

  }


}
